let interviewState=null;
async function openInterviews(){
 if(editor||profileDirty||sessionDirty||researchDirty||decisionDirty||alternativesDirty||scopeDirty||pilotDirty||scenarioDirty||sectionDirty||suggestionDirty||templateDirty||importDirty||commentDirty||inboxDirty||conversationDirty||findingDirty||provenanceDirty||retentionDirty||classificationDirty||researchConflictDirty||experimentDirty||reviewPackageDirty||reviewFeedbackDirty||feedbackDecisionDirty||responsibilityDirty||taskDirty||supportDirty||reportDirty||summaryDirty||exportDirty||contextDirty||restorationDirty)throw Error('Save or discard your edits before preparing an interview.');
 const data=await api('interviews',{ref:selected});interviewState={...data,preview:null};screen('interviews');$('interviews-title').focus();$('interview-preview').hidden=true;$('interview-read').hidden=true;
 $('interview-limits').textContent=data.partial?'Newest 100 preparation records shown. Earlier records remain in the project.':'Guides and logs are separate artifacts. No answers are inserted into an empty log. Recording actual observations is a separate workflow.';
 list('interview-offers',data.offers,'No readable current offer. Save an offer first; inspect unavailable drafts from the project overview.',(li,row)=>{title(li,'Offer version '+row.version+' · '+(row.client||'Context unknown')+' · '+row.id);detail(li,row.status);const b=document.createElement('button');b.textContent='Preview questions';b.disabled=data.archived;b.addEventListener('click',()=>act(()=>previewInterview('guide',row.id)));li.append(b);});
 list('interview-saved',data.saved,'No preparation saved yet.',(li,row)=>{title(li,(row.kind==='guide'?'Interview guide':row.kind==='blank_log'?'Empty interview log':'Unavailable preparation')+' · '+row.id);if(row.unavailable){detail(li,'Original details unavailable. Inspect or restore the original artifact.');return;}detail(li,'Original context: '+row.basis_id+(row.requires_review?' · Review required':''));const read=document.createElement('button');read.textContent='Read saved preparation';read.addEventListener('click',()=>{$('interview-read').textContent=row.markdown;$('interview-read').hidden=false;$('interview-read').focus();});li.append(read);if(row.kind==='guide'){const b=document.createElement('button');b.textContent='Preview a separate blank log';b.disabled=data.archived||row.requires_review;b.addEventListener('click',()=>act(()=>previewInterview('blank_log',row.id)));li.append(b);}});
}
async function previewInterview(kind,basis){const result=await api('interview-preview',{ref:selected,revision:interviewState.revision,sha256:interviewState.sha256,kind,basis});interviewState.preview=result.preview;$('interview-preview-text').textContent=result.markdown;$('interview-confirm').checked=false;$('interview-preview').hidden=false;$('interview-preview-text').focus();}
$('open-interviews').addEventListener('click',()=>act(openInterviews));
$('interviews-back').addEventListener('click',()=>act(()=>show(selected)));
$('interview-save').addEventListener('click',()=>act(async()=>{const result=await api('interview-save',{ref:selected,preview:interviewState?.preview,confirmed:$('interview-confirm').checked});await refresh();await openInterviews();notice('Preparation saved in revision '+result.revision+'. No interview, answers or evidence were recorded.');}));

