function comparisonRows(raw=false){return [...$('alternatives-rows').children].map(card=>({kind:card.dataset.kind,name:raw?card.querySelector('[name="name"]').value:card.querySelector('[name="name"]').value.trim(),...Object.fromEntries(Object.keys(optionFields).map(key=>[key,raw?card.querySelector('[name="'+key+'"]').value:card.querySelector('[name="'+key+'"]').value.trim()||null])),source_ids:[...card.querySelectorAll('input[type="checkbox"]:checked')].map(x=>x.value)}));}
