 for(const [tag,label]of [['amount_field','Amount-bearing fields'],['terms_or_scope','Terms and scope'],['number_fragments','Changed number fragments']]){const rows=result.changes.filter(r=>r.tags.includes(tag));if(!rows.length)continue;const heading=document.createElement('h2');heading.textContent=label;$('comparison-fields').append(heading);const links=document.createElement('ul');for(const row of rows){const li=document.createElement('li'),jump=document.createElement('button');jump.type='button';jump.className='quiet';jump.textContent=row.label;jump.addEventListener('click',()=>{const card=$('comparison-field-'+row.key);card.scrollIntoView({block:'start'});card.focus();});li.append(jump);links.append(li);}$('comparison-fields').append(links);}
