function guardSourceRemoval(){if(editor||wizardDirty||profileDirty||sessionDirty||researchDirty||decisionDirty||alternativesDirty||scopeDirty||pilotDirty||scenarioDirty||sectionDirty||suggestionDirty||templateDirty||importDirty||commentDirty||inboxDirty||conversationDirty||findingDirty||provenanceDirty||retentionDirty||classificationDirty||researchConflictDirty||experimentDirty||reviewPackageDirty||reviewFeedbackDirty||feedbackDecisionDirty||responsibilityDirty||taskDirty||supportDirty||reportDirty||summaryDirty||exportDirty||contextDirty||restorationDirty)throw Error('Save or discard your current form before reviewing source removal.');}
