 $('source-removal-title').textContent=recovering?'Review pending source removal':'Review permanent source removal';$('source-removal-context').textContent=recovering?'Operation: '+data.operation_id+' · Some files may already have been removed.':'Selected source: '+data.title;$('source-removal-warning').textContent=data.warning;
