 inboxState=conversationState=findingState=provenanceState=retentionState=classificationState=researchConflictState=null;for(const section of ['insight-timeline','research-conflicts','research-conflict-editor','finding-classifications','classification-editor','source-inbox','conversations','findings','inbox-read','inbox-editor','conversation-read','conversation-editor','finding-read','finding-editor','source-provenance','provenance-read','provenance-editor','source-management'])for(const element of $(section).querySelectorAll('pre[id],p[id],ul[id],textarea,input')){if('value' in element){element.value='';if(element.type==='checkbox')element.checked=false;}else element.replaceChildren();}$('provenance-blocks').replaceChildren();$('conversation-blocks').replaceChildren();for(const id of ['research-conflict-left-choice','research-conflict-right-choice','conversation-source','finding-source','classification-assumption'])$(id).replaceChildren();
