 if(row)for(const source of row.coverage.source_relations)$('classification-current-assumption').textContent+='\nSource: '+source.title+' · '+source.finding_ids.length+' linked finding(s)'+(source.context_source_id?' · Recorded context source: '+source.context_source_id+' (possible dependence, not verified origin)':source.status==='unavailable'?' · Context relation unavailable; independence unknown':' · No context relation recorded; independence unknown');
 for(const category of Object.keys(classificationLabels))list('classification-'+category,row?.groups[category]??[],'No findings in this group.',(li,item)=>{title(li,item.finding.fragment.title);detail(li,'Source: '+item.finding.source_status+' · '+item.finding.same_fragment_links+' link(s) to this fragment, not independent observations');if(item.classification){detail(li,'Last judgment: '+classificationLabels[item.classification.input.stance]);const reason=document.createElement('pre');reason.textContent=item.classification.input.reason+'\n'+classificationScopeText(item.classification.input);li.append(reason);}for(const reason of item.review_reasons)detail(li,reason);const button=document.createElement('button');button.type='button';button.textContent=classificationState.archived?'Read judgment history':'Review finding and judgment';button.addEventListener('click',()=>openClassificationEditor(item));li.append(button);});
