function feedbackComparisonText(c,historical=false){return ['Original document: '+c.original_document+' | v'+c.original_version,'Original section ['+c.before.assertion+']:',c.before.value??'Unknown - not recorded','',(historical?'Compared document at response time: ':'Current document: ')+c.current_document+' | v'+c.current_version,(historical?'Compared section [':'Current section [')+c.after.assertion+']:',c.after.value??'Unknown - not recorded','','Text changed: '+c.text_changed+' | Version changed: '+c.version_changed+' | Basis/context needs review: '+c.context_changed,'No comment will be moved to the current document.'].join('\n');}
function feedbackChoiceText(row){return ['Original feedback:',row.original_comment,'','Owner alias: '+row.input.owner_alias,'Choice: '+row.input.choice,'Reason: '+row.input.reason,...(row.input.adapted_feedback===null?[]:['Adapted feedback:',row.input.adapted_feedback]),'',feedbackComparisonText(row.comparison,true),row.warning].join('\n');}
