$('feedback-decision-back').addEventListener('click',()=>act(async()=>{feedbackDecisionDirty=false;clearRecovery('feedback-decision');feedbackDecisionState=null;await openReviewFeedback();}));

function responsibilityText(row){return ['Task: '+row.task_id,'Previous owner: '+(row.before.owner_alias??'Not recorded'),'New owner: '+(row.after.owner_alias??'Not recorded'),'Previous prerequisites: '+(row.before.depends_on.join(', ')||'None'),'New prerequisites: '+(row.after.depends_on.join(', ')||'None'),'Reason: '+row.reason,row.warning].join('\n');}
function selectResponsibilityTask(id){const task=responsibilityState.tasks.find(t=>t.id===id);responsibilityState.task=task??null;$('responsibility-form').hidden=!task||responsibilityState.archived;$('responsibility-preview').hidden=true;$('responsibility-confirm').checked=false;responsibilityState.preview=null;$('responsibility-history').replaceChildren();$('responsibility-dependencies').replaceChildren();if(!task)return;$('responsibility-owner').value=task.owner_alias??'';$('responsibility-reason').value='';const all=[...responsibilityState.tasks,...responsibilityState.checks].filter(t=>t.id!==id),chosen=new Set(task.depends_on??[]),unselected=all.filter(t=>!chosen.has(t.id)),visible=[...all.filter(t=>chosen.has(t.id)),...unselected.slice(0,500)];$('responsibility-limits').textContent=(unselected.length>500?'First 500 unselected candidates plus every saved prerequisite shown. ':'All candidates shown. ')+'Existing selections are retained; no prerequisite is inferred from an alias.';for(const target of visible){const label=document.createElement('label'),check=document.createElement('input');label.className='check';check.type='checkbox';check.value=target.id;check.checked=chosen.has(target.id);label.append(check,document.createTextNode(target.title+' | '+target.id+' | '+target.progress+' / '+target.substantiation));$('responsibility-dependencies').append(label);}for(const row of task.history){const pre=document.createElement('pre');pre.textContent=responsibilityText(row);$('responsibility-history').append(pre);}if(!task.history.length)$('responsibility-history').textContent='No responsibility changes recorded.';}
async function openResponsibilities(taskId=null){if(editor||wizardDirty||profileDirty||sessionDirty||researchDirty||decisionDirty||alternativesDirty||scopeDirty||pilotDirty||scenarioDirty||sectionDirty||suggestionDirty||templateDirty||importDirty||commentDirty||inboxDirty||conversationDirty||findingDirty||provenanceDirty||retentionDirty||classificationDirty||researchConflictDirty||experimentDirty||reviewPackageDirty||reviewFeedbackDirty||feedbackDecisionDirty||responsibilityDirty||taskDirty||supportDirty||reportDirty||summaryDirty||exportDirty||contextDirty||restorationDirty)throw Error('Save or discard your current form first.');const data=await api('task-responsibilities',{ref:selected});responsibilityState={...data,ref:selected,task:null,preview:null};responsibilityDirty=false;screen('responsibilities');$('responsibilities-title').focus();$('responsibilities-status').textContent=data.warning+(data.archived?' Archived project: read only.':'')+(!data.tasks.length?' No tasks recorded.':'');const select=$('responsibility-task');select.replaceChildren();for(const task of data.tasks){const option=document.createElement('option');option.value=task.id;option.textContent=task.title+' | '+task.id+' | '+(task.owner_alias??'No recorded owner');select.append(option);}select.value=data.tasks.some(t=>t.id===taskId)?taskId:data.tasks[0]?.id??'';selectResponsibilityTask(select.value);}
$('open-responsibilities').addEventListener('click',()=>act(()=>openResponsibilities()));
$('responsibility-task').addEventListener('change',()=>{if(responsibilityDirty){$('responsibility-task').value=responsibilityState.task.id;notice('Save or discard your edits before choosing another task.',true);return;}selectResponsibilityTask($('responsibility-task').value);});
$('responsibility-form').addEventListener('input',()=>{responsibilityDirty=true;responsibilityState.preview=null;$('responsibility-preview').hidden=true;$('responsibility-confirm').checked=false;keepDraft();});
$('responsibility-form').addEventListener('submit',event=>{event.preventDefault();act(async()=>{const state=responsibilityState,assignment={task_id:state.task.id,previous:state.task.last_responsibility,owner_alias:$('responsibility-owner').value.trim()||null,depends_on:[...$('responsibility-dependencies').querySelectorAll('input:checked')].map(e=>e.value),reason:$('responsibility-reason').value};const result=await api('task-responsibility-preview',{ref:state.ref,revision:state.revision,sha256:state.sha256,assignment});state.preview=result.preview;responsibilityDirty=true;$('responsibility-text').textContent=[responsibilityText(result.details),'','New review flags: '+(result.review_required.join(', ')||'None'),'Task progress after save: '+result.task_after.progress,'Task substantiation after save: '+result.task_after.substantiation,'Selected prerequisite statuses:',...result.dependency_statuses.map(t=>t.title+' | '+t.id+' | '+t.progress+' / '+t.applicability+' / '+t.substantiation)].join('\n');$('responsibility-confirm').checked=false;$('responsibility-preview').hidden=false;$('responsibility-text').focus();});});
$('responsibility-save').addEventListener('click',()=>act(async()=>{if(!responsibilityState?.preview||!$('responsibility-confirm').checked)throw Error('Confirm this exact responsibility change.');const state=responsibilityState,result=await api('task-responsibility-save',{ref:state.ref,preview:state.preview,confirmed:true});responsibilityDirty=false;clearRecovery('responsibility');await openResponsibilities(state.task.id);notice('Responsibility saved at revision '+result.revision+'. No notification or access grant was made.');}));
$('responsibilities-back').addEventListener('click',()=>act(async()=>{responsibilityDirty=false;clearRecovery('responsibility');responsibilityState=null;await show(selected);}));
